/** Copie verbatim de `global/hooks/identity-guard.mjs` (sha256 01f6f9f135c8). */
export const IDENTITY_GUARD_MJS: string =
  "#!/usr/bin/env node\n// identity-guard.mjs — Garde d'identite iakaframe (portage macOS du .ps1)\n// Cable sur les hooks Stop et SubagentStop. Verifie que le TOUR courant OUVRE et\n// CLOT par un badge. La POSITION de la pastille porte le sens :\n//   ouverture = pastille AVANT le bloc  ->  🟡 [PORTEFEUILLE][Odin]\n//   cloture   = pastille APRES le bloc  ->  [PORTEFEUILLE][Odin] 🟡\n// ASSOUPLISSEMENT : l'ouverture est acceptee si N'IMPORTE QUEL message-texte du tour\n// (depuis le dernier vrai prompt user ; les tool_result ne ferment pas le tour) ouvre\n// par un badge. La cloture, elle, reste portee par le DERNIER message du tour.\n// ANTI-COURSE DE FLUSH : si le verdict serait un refus, on attend brievement et on\n// RELIT le transcript (jusqu'a 3 essais). Cela neutralise le cas ou le hook Stop lit\n// le fichier avant que le dernier message-texte (porteur du badge de cloture) y soit\n// ecrit -> sinon une narration d'outil intermediaire, sans badge, declenche un faux refus.\n// Badge manquant -> exit 2 (refus, stderr renvoye a l'agent). FAIL-OPEN : tout bug\n// interne => exit 0. Respecte stop_hook_active (anti-boucle).\n//\n// LIMITE ASSUMEE : ce garde ne lit que le canal ADRESSE (blocs type:\"text\").\n// Les gestes (tool_use) lui sont invisibles -> voir delegation-guard.mjs.\n\nimport { readFileSync } from \"node:fs\";\n\nconst allow = () => process.exit(0);\nconst block = (msg) => { process.stderr.write(msg + \"\\n\"); process.exit(2); };\n\n// Sommeil synchrone (pas d'async dans un hook one-shot) sans dependance externe.\nconst sleep = (ms) => {\n  try { Atomics.wait(new Int32Array(new SharedArrayBuffer(4)), 0, 0, ms); }\n  catch { /* SharedArrayBuffer indispo -> on n'attend pas, simple degradation */ }\n};\n\nconst PASTILLES = [0x1f7e1, 0x1f535, 0x1f534, 0x1f7e2, 0x1f7e3, 0x1f7e0]\n  .map((cp) => String.fromCodePoint(cp));\nconst pastAlt = PASTILLES.map((p) => p.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\")).join(\"|\");\nconst bracket = \"\\\\[[^\\\\]]+\\\\]\\\\s*`?\\\\s*\\\\[[^\\\\]]+\\\\]\"; // [ROYAUME][Agent]\nconst reOpen = new RegExp(\"^(?:\" + pastAlt + \")\\\\s*`?\\\\s*\" + bracket);\nconst reClose = new RegExp(bracket + \"\\\\s*`?\\\\s*(?:\" + pastAlt + \")(?:\\\\s|$)\");\n\nconst linesOf = (txt) =>\n  txt.split(\"\\n\").map((l) => l.replace(/\\s+$/, \"\")).filter((l) => l.trim() !== \"\");\n\n// Evalue l'etat courant du transcript. Renvoie :\n//   { skip: true }                      -> rien a juger (transcript illisible/vide) => allow\n//   { skip: false, startOk, stopOk }    -> verdict sur le tour courant\nfunction evaluate(tp) {\n  let lines;\n  try { lines = readFileSync(tp, \"utf8\").split(/\\r?\\n/); }\n  catch { return { skip: true }; }\n\n  // Messages assistant-texte du TOUR courant, du plus recent au plus ancien.\n  // Le tour s'arrete au dernier VRAI prompt user (un tool_result ne ferme pas le tour).\n  const turn = []; // ordre anti-chronologique (turn[0] = dernier message)\n  for (let i = lines.length - 1; i >= 0; i--) {\n    const line = lines[i].trim();\n    if (!line) continue;\n    let obj;\n    try { obj = JSON.parse(line); } catch { continue; }\n\n    if (obj.type === \"user\" && obj.message) {\n      const c = obj.message.content;\n      // tool_result pur => fait partie du tour, on continue ; sinon = vrai prompt => frontiere.\n      const isToolResultOnly = Array.isArray(c) && c.length > 0\n        && c.every((p) => p && p.type === \"tool_result\");\n      if (isToolResultOnly) continue;\n      break;\n    }\n\n    if (obj.type === \"assistant\" && obj.message && Array.isArray(obj.message.content)) {\n      const parts = obj.message.content\n        .filter((c) => c.type === \"text\" && c.text)\n        .map((c) => String(c.text));\n      if (parts.length) turn.push(parts.join(\"\\n\").trim());\n    }\n  }\n  if (turn.length === 0) return { skip: true };\n\n  // Ouverture : acceptee si N'IMPORTE QUEL message-texte du tour ouvre par un badge.\n  const opensWith = (txt) => {\n    const ne = linesOf(txt);\n    return ne.length > 0 && reOpen.test(ne[0].trim());\n  };\n  let startOk = turn.some(opensWith);\n\n  // Cloture : portee par le DERNIER message-texte du tour (turn[0]).\n  const nonEmpty = linesOf(turn[0]);\n  let stopOk;\n  if (nonEmpty.length === 1) {\n    const single = reOpen.test(nonEmpty[0].trim()) || reClose.test(nonEmpty[0].trim());\n    stopOk = single;\n    // Tour reduit a un unique one-liner : on tolere ouverture OU cloture pour les deux.\n    if (turn.length === 1) startOk = single;\n  } else {\n    stopOk = false;\n    const idxs = [nonEmpty.length - 1];\n    if (nonEmpty.length >= 3) idxs.push(nonEmpty.length - 2);\n    for (const idx of idxs) {\n      if (idx === 0) continue;\n      if (reClose.test(nonEmpty[idx].trim())) { stopOk = true; break; }\n    }\n  }\n\n  return { skip: false, startOk, stopOk };\n}\n\ntry {\n  const raw = readFileSync(0, \"utf8\");\n  if (!raw.trim()) allow();\n  const payload = JSON.parse(raw);\n  if (payload.stop_hook_active) allow();\n\n  const tp = payload.transcript_path;\n  if (!tp) allow();\n\n  // Boucle anti-course : on ne bloque qu'apres avoir laisse le flush se terminer.\n  const ATTEMPTS = 3;\n  const WAIT_MS = 150;\n  let res = { skip: true };\n  for (let attempt = 0; attempt < ATTEMPTS; attempt++) {\n    res = evaluate(tp);\n    if (res.skip || (res.startOk && res.stopOk)) allow();\n    if (attempt < ATTEMPTS - 1) sleep(WAIT_MS); // laisser ecrire le dernier message\n  }\n\n  const miss = [];\n  if (!res.startOk) miss.push(\"ouverture (pastille AVANT le bloc en PREMIERE ligne, ex: 🟡 [ROYAUME][Agent])\");\n  if (!res.stopOk) miss.push(\"cloture (pastille APRES le bloc en derniere ligne, ex: [ROYAUME][Agent] 🟡)\");\n  block(\n    \"Garde d'identite iakaframe : badge manquant -> \" + miss.join(\" + \") +\n    \". Convention : ouverture = pastille AVANT, cloture = pastille APRES.\"\n  );\n} catch {\n  allow(); // fail-open : un bug du garde ne fige jamais une session\n}\n";

/** Copie verbatim de `global/hooks/identity-remind.mjs` (sha256 3c256eb8e739). */
export const IDENTITY_REMIND_MJS: string =
  "#!/usr/bin/env node\n// identity-remind.mjs — Rappel d'identite iakaframe (hook UserPromptSubmit, portage macOS).\n// Le stdout est injecte comme contexte additionnel avant la reponse de l'agent.\n// Nudge doux, complement du garde bloquant identity-guard.mjs (Stop/SubagentStop).\n\nprocess.stdout.write(\n  \"[Garde d'identite iakaframe] Regle de la methode : tout agent qui prend la parole \" +\n  \"s'identifie ET annonce ce qu'il fait. La POSITION de la pastille porte le sens. \" +\n  \"Ouverture = pastille AVANT le bloc, en TOUTE PREMIERE ligne -> <pastille> [ROYAUME][Agent] \" +\n  \"(ex: pastille jaune puis [PORTEFEUILLE][Odin]) suivi d'une courte annonce ; \" +\n  \"cloture = pastille APRES le bloc en derniere ligne -> [ROYAUME][Agent] <pastille>. \" +\n  \"Double badge par intervention. Une delegation = chaine de badges.\\n\"\n);\nprocess.exit(0);\n";

/** Copie verbatim de `global/hooks/perimeter-guard.mjs` (sha256 eb6c334edfc3). */
export const PERIMETER_GUARD_MJS: string =
  "#!/usr/bin/env node\n// perimeter-guard.mjs — Garde iakaframe du canal des GESTES DIRECTS (Edit/Write/Bash/NotebookEdit).\n// Cable sur PreToolUse, matcher \"Edit|Write|Bash|NotebookEdit\".\n//\n// Pourquoi : delegation-guard.mjs ne garde QUE l'outil Task (delegation). Les gestes mutateurs\n// DIRECTS (Edit/Write/Bash/NotebookEdit) ne sont gardes par aucun hook -> faille de perimetre\n// (un Edit/commit hors du projet courant passe non controle). Ce garde detecte le(s) chemin(s)\n// touche(s), journalise, et selon le mode signale (WARN, exit 0) ou bloque (DENY, exit 2) un\n// geste qui SORT du perimetre autorise.\n//\n// PRINCIPE : garde de CHEMINS, jamais de personas (la persona iakaframe est absente du payload).\n// ANCRAGE : $CLAUDE_PROJECT_DIR (stable), PAS le cwd du payload (qui derive). Variable absente\n// -> SKIP (fail-open, exit 0).\n// FAIL-OPEN partout : tout bug interne => exit 0. Journal : ~/.claude/iakaframe-perimeter.log\n\nimport { appendFileSync, readFileSync } from \"node:fs\";\nimport { homedir } from \"node:os\";\nimport { isAbsolute, join, relative, resolve } from \"node:path\";\n\nconst LOG = join(homedir(), \".claude\", \"iakaframe-perimeter.log\");\nconst CLAUDE_DIR = join(homedir(), \".claude\");\nconst HARNESS_SETTINGS = join(CLAUDE_DIR, \"settings.json\");\n\nconst allow = () => process.exit(0);\nconst ts = () => new Date().toISOString();\nconst write = (rec) => {\n  try { appendFileSync(LOG, JSON.stringify(rec) + \"\\n\", \"utf8\"); } catch { /* fail-open */ }\n};\n\n// Appartenance : target est SOUS base si relative(base, target) ne sort pas (pas de \"..\",\n// pas un chemin absolu). relative(\"/a\", \"/a\") === \"\" -> dans la base (la racine elle-meme).\nconst isUnder = (base, target) => {\n  if (!base || !target) return false;\n  const rel = relative(base, target);\n  return rel === \"\" || (!rel.startsWith(\"..\") && !isAbsolute(rel));\n};\n\n// Resout le mode EFFECTIF pour un outil donne, a partir de la valeur brute de la variable.\n// Renvoie \"deny\" ou \"warn\".\nconst effectiveMode = (modeEnv, tool) => {\n  const v = String(modeEnv || \"\").trim().toLowerCase();\n  if (v === \"deny\") return \"deny\";\n  if (v === \"warn\") return \"warn\";\n  // default | \"\" | inconnu => panachage par outil\n  return tool === \"Bash\" ? \"warn\" : \"deny\";\n};\n\n// Classe un chemin absolu resolu contre perimetre + listes blanches.\n// Renvoie un verdict : ALLOW_PROJECT | ALLOW_PORTFOLIO | DENY_HARNESS | HORS\nconst classifyPath = (absPath, projectDir) => {\n  // DENY harnais prime sur tout (settings.json sous ~/.claude/).\n  if (absPath === HARNESS_SETTINGS) return \"DENY_HARNESS\";\n  if (projectDir && isUnder(projectDir, absPath)) return \"ALLOW_PROJECT\";\n  // ALLOW portefeuille : ~/.claude/ (hors settings.json deja capte ci-dessus).\n  if (isUnder(CLAUDE_DIR, absPath)) return \"ALLOW_PORTFOLIO\";\n  return \"HORS\";\n};\n\nconst isBlocking = (verdict) => verdict === \"HORS\" || verdict === \"DENY_HARNESS\";\n\ntry {\n  const raw = readAll();\n  if (!raw.trim()) allow();\n  const p = JSON.parse(raw);\n  const event = p.hook_event_name || \"\";\n  if (event !== \"PreToolUse\") allow();\n\n  const session = p.session_id || null;\n  const tool = p.tool_name || \"\";\n  const ti = p.tool_input || {};\n  const payloadCwd = p.cwd || process.cwd();\n  const modeEnvRaw = process.env.IAKAFRAME_PERIMETER_MODE;\n  const modeEnv = (modeEnvRaw == null || modeEnvRaw === \"\") ? \"default\" : modeEnvRaw;\n\n  // Ancrage stable : $CLAUDE_PROJECT_DIR. Absent -> SKIP (fail-open).\n  const projectDirRaw = process.env.CLAUDE_PROJECT_DIR;\n  if (!projectDirRaw || !projectDirRaw.trim()) {\n    write({\n      at: ts(), event: \"SKIP\", session, tool: tool || null, path: null,\n      project_dir: null, verdict: \"SKIP\", reason: \"no_project_dir\",\n      mode: effectiveMode(modeEnv, tool), mode_env: modeEnv,\n    });\n    allow();\n  }\n  const projectDir = resolve(projectDirRaw);\n\n  // Resout un chemin (absolu garde tel quel ; relatif resolu contre le cwd du payload).\n  const toAbs = (pth) => isAbsolute(pth) ? resolve(pth) : resolve(payloadCwd, pth);\n\n  // ---- Cas Edit / Write / NotebookEdit : chemin explicite FIABLE ----\n  if (tool === \"Edit\" || tool === \"Write\" || tool === \"NotebookEdit\") {\n    const rawPath = ti.file_path || ti.notebook_path || null;\n    const mode = effectiveMode(modeEnv, tool);\n    if (!rawPath) {\n      // Pas de chemin -> on ne devine pas (fail-open).\n      write({\n        at: ts(), event: \"GESTE\", session, tool, path: null,\n        project_dir: projectDir, verdict: \"SKIP\", reason: \"no_path\",\n        mode, mode_env: modeEnv,\n      });\n      allow();\n    }\n    const abs = toAbs(rawPath);\n    const verdict = classifyPath(abs, projectDir);\n    write({\n      at: ts(), event: \"GESTE\", session, tool, path: abs,\n      project_dir: projectDir, verdict, mode, mode_env: modeEnv,\n    });\n    if (isBlocking(verdict)) {\n      const why = verdict === \"DENY_HARNESS\"\n        ? \"auto-modification du harnais (~/.claude/settings.json) reservee a l'humain\"\n        : \"chemin HORS perimetre projet\";\n      const msg =\n        \"[perimeter-guard] Geste \" + tool + \" \" + (mode === \"deny\" ? \"REFUSE\" : \"HORS PERIMETRE\") +\n        \" : \" + why + \".\\n  Cible    : \" + abs +\n        \"\\n  Perimetre: \" + projectDir +\n        \"\\n  Verdict  : \" + verdict + \" (mode=\" + mode + \").\\n\" +\n        (mode === \"deny\"\n          ? \"  Passe par la delegation (Aragorn/royaume) plutot qu'un geste direct hors perimetre,\\n  ou exporte IAKAFRAME_PERIMETER_MODE=warn pour desamorcer.\\n\"\n          : \"  (WARN : geste laisse passer mais journalise.)\\n\");\n      process.stderr.write(msg);\n      if (mode === \"deny\") process.exit(2);\n    }\n    allow();\n  }\n\n  // ---- Cas Bash : heuristique sur la chaine shell (MVP honnete) ----\n  if (tool === \"Bash\") {\n    const command = String(ti.command || \"\");\n    const mode = effectiveMode(modeEnv, tool);\n    const cmdShort = command.length > 500 ? command.slice(0, 500) + \"…\" : command;\n\n    const absPaths = extractAbsPaths(command);\n    if (absPaths.length === 0) {\n      // Aucun chemin absolu identifiable -> on ne devine pas. BASH_UNRESOLVED, toujours exit 0.\n      write({\n        at: ts(), event: \"GESTE\", session, tool, path: null, command: cmdShort,\n        project_dir: projectDir, verdict: \"BASH_UNRESOLVED\", mode, mode_env: modeEnv,\n      });\n      allow();\n    }\n\n    // Classer chaque chemin absolu ; un HORS ou DENY_HARNESS suffit a declencher.\n    let worst = \"ALLOW_PROJECT\"; // pire verdict rencontre (priorite DENY_HARNESS > HORS > autres)\n    const classified = [];\n    for (const ap of absPaths) {\n      const v = classifyPath(ap, projectDir);\n      classified.push({ path: ap, verdict: v });\n      if (v === \"DENY_HARNESS\") worst = \"DENY_HARNESS\";\n      else if (v === \"HORS\" && worst !== \"DENY_HARNESS\") worst = \"HORS\";\n    }\n\n    write({\n      at: ts(), event: \"GESTE\", session, tool, path: classified, command: cmdShort,\n      project_dir: projectDir, verdict: worst, mode, mode_env: modeEnv,\n    });\n\n    if (isBlocking(worst)) {\n      const offenders = classified.filter((c) => isBlocking(c.verdict)).map((c) => c.path);\n      const why = worst === \"DENY_HARNESS\"\n        ? \"auto-modification du harnais (~/.claude/settings.json) reservee a l'humain\"\n        : \"chemin(s) absolu(s) HORS perimetre projet\";\n      const msg =\n        \"[perimeter-guard] Commande Bash \" + (mode === \"deny\" ? \"REFUSEE\" : \"HORS PERIMETRE\") +\n        \" : \" + why + \".\\n  Chemin(s): \" + offenders.join(\", \") +\n        \"\\n  Perimetre: \" + projectDir +\n        \"\\n  Verdict  : \" + worst + \" (mode=\" + mode + \").\\n\" +\n        (mode === \"deny\"\n          ? \"  Passe par la delegation plutot qu'un geste direct hors perimetre,\\n  ou exporte IAKAFRAME_PERIMETER_MODE=warn pour desamorcer.\\n\"\n          : \"  (WARN : commande laissee passer mais journalisee. Heuristique non exhaustive.)\\n\");\n      process.stderr.write(msg);\n      if (mode === \"deny\") process.exit(2);\n    }\n    allow();\n  }\n\n  // Outil non concerne (matcher large) -> laisser passer.\n  allow();\n} catch {\n  allow(); // fail-open : un bug du garde ne fige jamais une session\n}\n\nfunction readAll() {\n  try { return readFileSync(0, \"utf8\"); }\n  catch { return \"\"; }\n}\n\n// Extrait les chemins absolus \"interessants\" d'une chaine shell.\n// MVP honnete : on capte les chemins absolus du foyer (/Users/sjupin/...) et ~/.claude/...\n// On NE pretend PAS parser le shell ; au moindre doute on n'attrape rien (-> BASH_UNRESOLVED).\nfunction extractAbsPaths(command) {\n  const out = new Set();\n  // 1) chemins absolus POSIX explicites sous /Users/<user>/...\n  //    (on borne au foyer pour eviter le bruit ; suffit a la faille demontree).\n  const home = homedir();\n  const homeEsc = home.replace(/[.*+?^${}()|[\\]\\\\]/g, \"\\\\$&\");\n  const reHome = new RegExp(homeEsc + \"(?:/[^\\\\s'\\\"`;|&><]*)?\", \"g\");\n  let m;\n  while ((m = reHome.exec(command)) !== null) {\n    if (m[0]) out.add(resolve(m[0]));\n  }\n  // 2) ~/.claude/... (tilde) -> resolu vers le foyer reel.\n  const reTilde = /~\\/\\.claude(?:\\/[^\\s'\"`;|&><]*)?/g;\n  while ((m = reTilde.exec(command)) !== null) {\n    const tail = m[0].slice(1); // enleve le ~\n    out.add(resolve(join(home, tail)));\n  }\n  return [...out];\n}\n";

/** Copie verbatim de `global/hooks/delegation-guard.mjs` (sha256 813662fea774). */
export const DELEGATION_GUARD_MJS: string =
  "#!/usr/bin/env node\n// delegation-guard.mjs — Garde iakaframe du canal GESTES (la faille diagnostiquee).\n// Cable sur PreToolUse + PostToolUse, matcher \"Task\" (outil de delegation a un sous-agent).\n//\n// Pourquoi : les gardes d'identite (identity-guard.mjs) ne lisent que le canal ADRESSE\n// (blocs texte) aux frontieres de parole (Stop/SubagentStop). La delegation, elle, est un\n// GESTE (tool_use) dont le payload echappe totalement a ces gardes. Ce script pose un garde\n// sur le bon canal :\n//   - PreToolUse  : journalise l'ALLER verbatim (agent cible + prompt envoye) et verifie que\n//                   l'agent cible appartient au roster connu. Rend l'aller auditable.\n//   - PostToolUse : journalise le RETOUR verbatim. Rend \"restitution verbatim\" verifiable\n//                   au lieu de reposer sur la seule bonne foi de l'orchestrateur. EMET aussi\n//                   (L5) un document MACHINE de delegation sur le canal geste vers iakaboxlogs.\n//\n// MVP honnete : ce garde rend les gestes AUDITABLES (il ne pretend pas policer\n// semantiquement les frontieres de role, ce qui n'est pas fiable). FAIL-OPEN : ne bloque\n// jamais un travail reel pour un bug interne. Journal : ~/.claude/iakaframe-delegations.log\n//\n// L5 — Tracage MACHINE des delegations (canal geste -> iakaboxlogs) :\n//   A PostToolUse, si subagent_type est un agent du ROSTER iakaframe, on EMET un document\n//   { role:\"system\", content:\"Delegation X -> Y : ...\", meta:{canal:\"geste\", event:\"delegation\",\n//   from, to, verdict?} } vers iakaboxlogs. Best-effort, NON BLOQUANT, fail-open total.\n//   Transport selectionnable par IAKALOG_TRANSPORT : \"mqtt\" (defaut, voie box) | \"couchdb\"\n//   (fallback recette offline, POST {COUCHDB_URL}/{db} Basic auth, calque sur bridge/index.js).\n//   _id deterministe (idempotence ; 409 = succes). Sous-agents natifs -> AUCUNE emission.\n//   Borne iakaframe : identite iakaboxlogs absente -> aucune emission, exit 0.\n\nimport { appendFileSync, readFileSync } from \"node:fs\";\nimport { homedir } from \"node:os\";\nimport { join } from \"node:path\";\nimport net from \"node:net\";\n\nconst LOG = join(homedir(), \".claude\", \"iakaframe-delegations.log\");\nconst ROSTER = new Set([\n  \"odin\", \"aragorn\", \"gandalf\", \"gimli\", \"legolas\", \"helm\", \"loki\", \"nathalie\",\n]);\n// Sous-agents Claude Code natifs tolere(s) hors roster iakaframe.\nconst BUILTINS = new Set([\n  \"Explore\", \"Plan\", \"general-purpose\", \"claude\", \"claude-code-guide\", \"statusline-setup\",\n]);\n\n// Plafond d'attente de l'emission. Le garde est un hook VIVANT (chaque Task, y compris\n// la session en cours) : on ne PEND JAMAIS. Au-dela, on abandonne et on laisse passer.\n// Declare ICI (avant `await main()`) : sinon TDZ -> ReferenceError avalee = 0 emission.\nconst EMIT_TIMEOUT_MS = 1500;\n\nconst allow = () => process.exit(0);\n\nconst ts = () => new Date().toISOString();\nconst write = (rec) => {\n  try { appendFileSync(LOG, JSON.stringify(rec) + \"\\n\", \"utf8\"); } catch { /* fail-open */ }\n};\n\nawait main();\n\nasync function main() {\n  try {\n  const raw = readAll();\n  if (!raw.trim()) allow();\n  let p;\n  try { p = JSON.parse(raw); } catch { allow(); return; }\n  const event = p.hook_event_name || \"\";\n  const session = p.session_id || null;\n\n  if (event === \"PreToolUse\") {\n    const ti = p.tool_input || {};\n    const agent = ti.subagent_type || ti.subagentType || \"(non precise)\";\n    write({\n      at: ts(), event: \"ALLER\", session,\n      agent,\n      description: ti.description || null,\n      prompt: ti.prompt ?? null, // verbatim, jamais reformule\n    });\n    const known = ROSTER.has(String(agent).toLowerCase()) || BUILTINS.has(String(agent));\n    if (!known && agent !== \"(non precise)\") {\n      // Hors roster connu -> REFUS (exit 2). L'ALLER est deja journalise ci-dessus.\n      write({ at: ts(), event: \"REFUS\", session, agent, raison: \"hors_roster\" });\n      // L5 : on EMET aussi la tentative refusee (signal methode), best-effort non bloquant,\n      // AVANT le refus (l'emission ne doit jamais empecher le refus de partir).\n      // Emission AWAITED + bornee + fail-open AVANT le refus (sinon process.exit la tue).\n      await emitDelegation({\n        session,\n        agent,\n        description: ti.description || null,\n        response: null,\n        atAller: ts(),\n        refused: true,\n      });\n      process.stderr.write(\n        \"[delegation-guard] Delegation REFUSEE : agent cible hors roster iakaframe : '\" + agent +\n        \"'. Roster autorise : \" + [...ROSTER].join(\", \") + \" (+ sous-agents natifs : \" +\n        [...BUILTINS].join(\", \") + \"). Corrige subagent_type, ou ajoute l'agent au roster du garde.\\n\"\n      );\n      process.exit(2);\n    }\n    allow();\n  }\n\n  if (event === \"PostToolUse\") {\n    const ti = p.tool_input || {};\n    const agent = (ti.subagent_type || ti.subagentType) || null;\n    const response = extractText(p.tool_response); // verbatim\n    write({\n      at: ts(), event: \"RETOUR\", session,\n      agent,\n      response,\n    });\n    // L5 : RETOUR = moment d'emission de reference (delegation complete : cible + resultat).\n    // Best-effort non bloquant ; n'emet QUE pour le roster iakaframe (anti-bruit D5).\n    // AWAITED + bornee : on flushe l'emission AVANT process.exit, sinon 0 doc en base.\n    await emitDelegation({\n      session,\n      agent,\n      description: ti.description || null,\n      response,\n      atAller: ts(),\n      refused: false,\n    });\n    allow();\n  }\n\n  allow();\n  } catch {\n    allow(); // fail-open\n  }\n}\n\nfunction readAll() {\n  try { return readFileSync(0, \"utf8\"); }\n  catch { return \"\"; }\n}\n\nfunction extractText(resp) {\n  if (resp == null) return null;\n  if (typeof resp === \"string\") return resp;\n  // tool_response peut etre un tableau de blocs {type:\"text\", text:\"...\"} ou un objet.\n  try {\n    if (Array.isArray(resp)) {\n      const t = resp.filter((c) => c && c.type === \"text\" && c.text).map((c) => c.text);\n      return t.length ? t.join(\"\\n\") : JSON.stringify(resp);\n    }\n    return typeof resp === \"object\" ? JSON.stringify(resp) : String(resp);\n  } catch { return String(resp); }\n}\n\n// ---------------------------------------------------------------------------\n// L5 — Emission MACHINE de la delegation (canal geste). Tout est fail-open : la\n// moindre anomalie est avalee, on ne casse JAMAIS la session ni le garde.\n// ---------------------------------------------------------------------------\n\n// Extraction best-effort du verdict (D4 / A4). Renseigne UNIQUEMENT si un marqueur\n// explicite PASS/FAIL existe dans la reponse ; absent sinon (pas de parsing intelligent).\nfunction deriveVerdict(response) {\n  if (!response || typeof response !== \"string\") return undefined;\n  // Marqueurs explicites : \"gate ... PASS\", \"PASS\", \"FAIL\", \"verdict: pass\", \"KO/OK gate\".\n  if (/\\bgate[^\\n]{0,40}\\bFAIL\\b/i.test(response) || /\\bverdict\\s*[:=]\\s*fail\\b/i.test(response)) return \"FAIL\";\n  if (/\\bgate[^\\n]{0,40}\\bPASS\\b/i.test(response) || /\\bverdict\\s*[:=]\\s*pass\\b/i.test(response)) return \"PASS\";\n  if (/\\bFAIL\\b/.test(response)) return \"FAIL\";\n  if (/\\bPASS\\b/.test(response)) return \"PASS\";\n  return undefined;\n}\n\n// _id deterministe (idempotence). 409 lors d'un POST = succes silencieux.\nfunction makeDocId(session, to, atAller, refused) {\n  const safe = (s) => String(s == null ? \"x\" : s).replace(/[^a-zA-Z0-9_-]/g, \"-\");\n  const kind = refused ? \"refused\" : \"deleg\";\n  return `${kind}-${safe(session)}-${safe(atAller)}-${safe(to)}`;\n}\n\n// Course fail-open : resout (timeout) au bout de ms quoi qu'il arrive ; jamais de reject.\nfunction withTimeout(promise, ms) {\n  return Promise.race([\n    Promise.resolve(promise).catch(() => \"error\"),\n    new Promise((resolve) => setTimeout(() => resolve(\"timeout\"), ms)),\n  ]).catch(() => \"error\");\n}\n\n// AWAITED + bornee + fail-open. main() doit AWAIT cet appel AVANT process.exit, sinon\n// l'emission ne part jamais (le defaut bloquant corrige en L5 : 0 doc en base).\nasync function emitDelegation({ session, agent, description, response, atAller, refused }) {\n  try {\n    const to = agent == null ? null : String(agent);\n    // D5 anti-bruit : on n'emet QUE pour le roster iakaframe. Les sous-agents natifs\n    // (Explore/Plan/general-purpose...) et un agent absent -> AUCUNE emission.\n    if (!to || !ROSTER.has(to.toLowerCase())) {\n      // Exception : une tentative refusee (hors roster) PEUT etre emise si demande.\n      // refused=true vient d'un agent hors roster ; on l'emet quand meme (signal methode).\n      if (!refused) return;\n    }\n\n    const from = process.env.IAKALOG_AGENT || \"unknown\";\n    const royaume = process.env.IAKALOG_ROYAUME || \"unknown\";\n\n    // D6 — Borne iakaframe : sans identite iakaboxlogs configuree, AUCUNE emission.\n    const transport = (process.env.IAKALOG_TRANSPORT || \"mqtt\").toLowerCase();\n    const hasMqttId = !!(process.env.IAKALOG_USER && process.env.IAKALOG_PASS);\n    const hasCouchId = !!(process.env.COUCHDB_URL &&\n      (process.env.COUCHDB_USER || process.env.COUCHDB_PASSWORD || process.env.COUCHDB_AUTH));\n    if (transport === \"couchdb\" ? !hasCouchId : !hasMqttId) return;\n\n    const verdict = deriveVerdict(response);\n    const conv = session || process.env.IAKALOG_CONV || \"default\";\n    const eventName = refused ? \"delegation_refused\" : \"delegation\";\n    const arrow = refused ? \"(REFUSE) \" : \"\";\n    const desc = description ? \" : \" + description : \"\";\n    const content = `Delegation ${arrow}${from} -> ${to || \"(inconnu)\"}${desc}`;\n    const meta = { canal: \"geste\", event: eventName, from, to: to || null };\n    if (verdict) meta.verdict = verdict;\n    if (refused) meta.refused = true;\n    const _id = makeDocId(session, to, atAller, refused);\n\n    const doc = { _id, role: \"system\", content, ts: atAller, tokens: 0, meta, royaume, agent: from, conv_id: conv };\n\n    // AWAITED mais BORNEE : on flushe l'emission, sans jamais depasser EMIT_TIMEOUT_MS.\n    if (transport === \"couchdb\") {\n      await withTimeout(emitCouchDB(doc), EMIT_TIMEOUT_MS);\n    } else {\n      await withTimeout(emitMqtt({ royaume, agent: from, conv, doc }), EMIT_TIMEOUT_MS);\n    }\n  } catch { /* fail-open : une emission ne doit jamais casser le garde */ }\n}\n\n// Transport CouchDB : POST {COUCHDB_URL}/{db} Basic auth (calque sur bridge/index.js).\n// AWAITED : on attend la reponse (flush) ; AbortController borne la requete ; 409 = succes\n// (idempotence). Toute erreur est avalee -> fail-open total, jamais de throw propage.\nasync function emitCouchDB(doc) {\n  const ctrl = new AbortController();\n  const t = setTimeout(() => { try { ctrl.abort(); } catch { /* noop */ } }, EMIT_TIMEOUT_MS);\n  try {\n    const base = String(process.env.COUCHDB_URL).replace(/\\/$/, \"\");\n    const db = process.env.COUCHDB_DB || \"conversations\";\n    const user = process.env.COUCHDB_USER || \"\";\n    const pass = process.env.COUCHDB_PASSWORD || \"\";\n    const auth = process.env.COUCHDB_AUTH ||\n      (\"Basic \" + Buffer.from(`${user}:${pass}`).toString(\"base64\"));\n    // fetch dispo en Node 18+. On AWAIT pour garantir le flush avant process.exit.\n    const res = await fetch(`${base}/${db}`, {\n      method: \"POST\",\n      headers: { \"Content-Type\": \"application/json\", Authorization: auth },\n      body: JSON.stringify(doc),\n      signal: ctrl.signal,\n    });\n    // 409 Conflict = le doc (meme _id) existe deja -> succes silencieux (idempotence).\n    if (res && res.status === 409) return \"exists\";\n    if (res && !res.ok) return \"http-\" + res.status;\n    return \"ok\";\n  } catch {\n    return \"error\"; // fail-open : timeout/abort/reseau -> on abandonne sans bloquer\n  } finally {\n    clearTimeout(t);\n  }\n}\n\n// Transport MQTT : publie sur iakaboxlogs/<royaume>/<agent>/<conv> (calque sur iakalog.mjs).\n// _id voyage dans le payload ; le bridge l'honore s'il est present. AWAITED + timeout court :\n// resout quand le PUBLISH est ecrit OU au timeout, jamais de reject (fail-open).\nfunction emitMqtt({ royaume, agent, conv, doc }) {\n  return new Promise((resolve) => {\n    let done = false;\n    const finish = (r) => { if (!done) { done = true; resolve(r); } };\n    try {\n      const url = process.env.IAKALOG_MQTT_URL || \"mqtt://192.168.2.11:1883\";\n      const u = url.match(/^mqtt:\\/\\/([^:/]+)(?::(\\d+))?/);\n      if (!u) return finish(\"bad-url\");\n      const host = u[1], port = parseInt(u[2] || \"1883\", 10);\n      const USER = process.env.IAKALOG_USER, PASS = process.env.IAKALOG_PASS;\n      const prefix = process.env.IAKALOG_PREFIX || \"iakaboxlogs\";\n      const topic = `${prefix}/${royaume}/${agent}/${conv}`;\n      const payload = JSON.stringify(doc);\n\n      const remLen = (n) => { const o = []; do { let d = n % 128; n = Math.floor(n / 128); if (n > 0) d |= 0x80; o.push(d); } while (n > 0); return Buffer.from(o); };\n      const mstr = (s) => { const b = Buffer.from(s, \"utf8\"); return Buffer.concat([Buffer.from([b.length >> 8, b.length & 0xff]), b]); };\n      const connectPkt = () => {\n        const rest = Buffer.concat([mstr(\"MQTT\"), Buffer.from([4, 0xC2, 0, 30]), mstr(\"delegguard-\" + process.pid), mstr(USER), mstr(PASS)]);\n        return Buffer.concat([Buffer.from([0x10]), remLen(rest.length), rest]);\n      };\n      const publishPkt = () => {\n        const body = Buffer.concat([mstr(topic), Buffer.from(payload, \"utf8\")]);\n        return Buffer.concat([Buffer.from([0x30]), remLen(body.length), body]);\n      };\n\n      const sock = net.connect({ host, port });\n      const timer = setTimeout(() => { try { sock.destroy(); } catch { /* noop */ } finish(\"timeout\"); }, EMIT_TIMEOUT_MS);\n      sock.on(\"error\", () => { clearTimeout(timer); try { sock.destroy(); } catch { /* noop */ } finish(\"error\"); });\n      let connacked = false;\n      sock.on(\"connect\", () => { try { sock.write(connectPkt()); } catch { /* noop */ } });\n      sock.on(\"data\", (d) => {\n        if (connacked || d[0] !== 0x20) return;\n        connacked = true;\n        if (d[3] !== 0) { clearTimeout(timer); try { sock.destroy(); } catch { /* noop */ } return finish(\"refused\"); }\n        try { sock.write(publishPkt(), () => { clearTimeout(timer); try { sock.end(); } catch { /* noop */ } finish(\"ok\"); }); }\n        catch { clearTimeout(timer); try { sock.destroy(); } catch { /* noop */ } finish(\"error\"); }\n      });\n    } catch { finish(\"error\"); }\n  });\n}\n";

/** Registre { nom de fichier → contenu verbatim } des scripts de garde disponibles. */
export const GUARD_SCRIPTS: Readonly<Record<string, string>> = {
  "identity-guard.mjs": IDENTITY_GUARD_MJS,
  "identity-remind.mjs": IDENTITY_REMIND_MJS,
  "perimeter-guard.mjs": PERIMETER_GUARD_MJS,
  "delegation-guard.mjs": DELEGATION_GUARD_MJS,
};
